customCSS:
.t, .history { color: #888888; }
.join { color: #99ad6a; }
.part, .quit { color: #888888; }
.kick, .error { color: #cf6a4c; }
.notice { color: #fad07a; }
.action { color: #c6b6ee; }
.mode, .nick, .topic, .server { color: #8fbfdc; }
.highlight { color: #e8e8d3; background-color: #404040; border-left: 3px solid #c6b6ee; padding-left: 8px; }
.reply { color: #888888; border-left: 2px solid #8197bf; padding-left: 6px; }
.oper { color: #151515; background-color: #fad07a; }
.reactions { color: #8197bf; background-color: #302028; }
.card { background-color: #302028; border-color: #888888; }
.card-title { color: #8197bf; }
.card-desc { color: #888888; }
.daychange { color: #888888; border-color: #302028; }
